private static void handleKeyBindings(PlayerTickEvent event) {
  Minecraft minecraft = Minecraft.getInstance();
  if (minecraft.player != null && minecraft.player == event.player && event.phase == Phase.START && event.side == LogicalSide.CLIENT && !minecraft.player.isSpectator()) {

    // jumping in mid air for double jump
    // ensure we pressed the key since the last tick, holding should not use all your jumps at once
    boolean isJumping = minecraft.options.keyJump.isDown();
    if (!wasJumping && isJumping) {
      if (TinkerEffects.antigravity.get().antigravityJump(event.player)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.ANTIGRAVITY_JUMP);
      }
      else if (DoubleJumpHandler.extraJump(event.player)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.DOUBLE_JUMP);
      }
    }
    wasJumping = isJumping;

    // helmet interaction
    boolean isHelmetInteracting = HELMET_INTERACT.isDown();
    if (!wasHelmetInteracting && isHelmetInteracting) {
      TooltipKey key = SafeClientAccess.getTooltipKey();
      if (InteractionHandler.startArmorInteract(event.player, EquipmentSlot.HEAD, key)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.getStartHelmetInteract(key));
      }
    }
    if (wasHelmetInteracting && !isHelmetInteracting) {
      if (InteractionHandler.stopArmorInteract(event.player, EquipmentSlot.HEAD)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.STOP_HELMET_INTERACT);
      }
    }

    // leggings interaction
    boolean isLeggingsInteract = LEGGINGS_INTERACT.isDown();
    if (!wasLeggingsInteracting && isLeggingsInteract) {
      TooltipKey key = SafeClientAccess.getTooltipKey();
      if (InteractionHandler.startArmorInteract(event.player, EquipmentSlot.LEGS, key)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.getStartLeggingsInteract(key));
      }
    }
    if (wasLeggingsInteracting && !isLeggingsInteract) {
      if (InteractionHandler.stopArmorInteract(event.player, EquipmentSlot.LEGS)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.STOP_LEGGINGS_INTERACT);
      }
    }

    wasHelmetInteracting = isHelmetInteracting;
    wasLeggingsInteracting = isLeggingsInteract;
  }
}

@Override
public void handleThreadsafe(Context context) {
  ServerPlayer player = context.getSender();
  if (player != null) {
    switch (this) {
      case DOUBLE_JUMP -> DoubleJumpHandler.extraJump(player);
      case ANTIGRAVITY_JUMP -> TinkerEffects.antigravity.get().antigravityJump(player);
      case START_HELMET_INTERACT, START_HELMET_INTERACT_SHIFT, START_HELMET_INTERACT_CONTROL, START_HELMET_INTERACT_ALT
        -> InteractionHandler.startArmorInteract(player, EquipmentSlot.HEAD, this.modifier);
      case STOP_HELMET_INTERACT -> InteractionHandler.stopArmorInteract(player, EquipmentSlot.HEAD);
      case START_LEGGINGS_INTERACT, START_LEGGINGS_INTERACT_SHIFT, START_LEGGINGS_INTERACT_CONTROL, START_LEGGINGS_INTERACT_ALT
        -> InteractionHandler.startArmorInteract(player, EquipmentSlot.LEGS, this.modifier);
      case STOP_LEGGINGS_INTERACT -> InteractionHandler.stopArmorInteract(player, EquipmentSlot.LEGS);
    }
  }
}

public static boolean startArmorInteract(Player player, EquipmentSlot slotType, TooltipKey modifierKey) {
  if (!player.isSpectator()) {
    ItemStack helmet = player.getItemBySlot(slotType);
    if (helmet.is(TinkerTags.Items.ARMOR)) {
      ToolStack tool = ToolStack.from(helmet);
      for (ModifierEntry entry : tool.getModifierList()) {
        if (entry.getHook(ModifierHooks.ARMOR_INTERACT).startInteract(tool, entry, player, slotType, modifierKey)) {
          // store data so we know when interaction started
          TinkerDataCapability.Holder data = TinkerDataCapability.getData(player);
          if (data != null) {
            data.computeIfAbsent(INTERACT_KEY).put(slotType, new ArmorInteractData(entry.getId(), player.tickCount));
          }
          break;
        }
      }
      return true;
    }
  }
  return false;
}

public static boolean stopArmorInteract(Player player, EquipmentSlot slotType) {
  if (!player.isSpectator()) {
    ItemStack helmet = player.getItemBySlot(slotType);
    if (helmet.is(TinkerTags.Items.ARMOR)) {
      ToolStack tool = ToolStack.from(helmet);
      // fetch interaction data if present
      int chargeTime = 0;
      ModifierEntry activeModifier = ModifierEntry.EMPTY;
      TinkerDataCapability.Holder data = TinkerDataCapability.getData(player);
      if (data != null) {
        Map<EquipmentSlot,ArmorInteractData> interactMap = data.get(INTERACT_KEY);
        if (interactMap != null) {
          ArmorInteractData interactData = interactMap.remove(slotType);
          if (interactData != null) {
            activeModifier = tool.getModifier(interactData.modifier);
            chargeTime = player.tickCount - interactData.startTime;
          }
        }
      }
      // run modifier hook for stop interact
      // TODO 1.21: consider only running hook on the active modifier
      for (ModifierEntry entry : tool.getModifierList()) {
        entry.getHook(ModifierHooks.ARMOR_INTERACT).stopInteract(tool, entry, player, slotType, chargeTime, activeModifier);
      }
      // cleanup drawtime on the tool
      GeneralInteractionModifierHook.finishUsing(tool);
      return true;
    }
  }
  return false;
}

default void stopInteract(IToolStackView tool, ModifierEntry modifier, Player player, EquipmentSlot slot, int chargeTime, ModifierEntry activeModifier) {
  stopInteract(tool, modifier, player, slot);
}

public static void register() {
  FMLJavaModLoadingContext.get().getModEventBus().addListener(EventPriority.NORMAL, false, RegisterCapabilitiesEvent.class, event -> event.register(PlayerLastEquipment.class));

  // equipment change is used on both sides
  MinecraftForge.EVENT_BUS.addListener(EquipmentChangeWatcher::onEquipmentChange);

  // only need to use the cap and the player tick on the client
  if (FMLEnvironment.dist == Dist.CLIENT) {
    MinecraftForge.EVENT_BUS.addListener(EquipmentChangeWatcher::onPlayerTick);
    MinecraftForge.EVENT_BUS.addGenericListener(Entity.class, EquipmentChangeWatcher::attachCapability);
  }
}

private static void onEquipmentChange(LivingEquipmentChangeEvent event) {
  runModifierHooks(event.getEntity(), event.getSlot(), event.getFrom(), event.getTo());
}

private static void runModifierHooks(LivingEntity entity, EquipmentSlot changedSlot, ItemStack original, ItemStack replacement) {
  EquipmentChangeContext context = new EquipmentChangeContext(entity, changedSlot, original, replacement);

  // first, fire event to notify an item was removed
  IToolStackView tool = context.getOriginalTool();
  if (tool != null && ModifierUtil.validArmorSlot(tool, changedSlot)) {
    for (ModifierEntry entry : tool.getModifierList()) {
      entry.getHook(ModifierHooks.EQUIPMENT_CHANGE).onUnequip(tool, entry, context);
    }
  }

  // next, fire event to notify an item was added
  tool = context.getReplacementTool();
  if (tool != null && ModifierUtil.validArmorSlot(tool, changedSlot)) {
    for (ModifierEntry entry : tool.getModifierList()) {
      entry.getHook(ModifierHooks.EQUIPMENT_CHANGE).onEquip(tool, entry, context);
    }
  }

  // finally, fire events on all other slots to say something changed
  for (EquipmentSlot otherSlot : EquipmentSlot.values()) {
    if (otherSlot != changedSlot) {
      tool = context.getValidTool(otherSlot);
      if (tool != null) {
        for (ModifierEntry entry : tool.getModifierList()) {
          entry.getHook(ModifierHooks.EQUIPMENT_CHANGE).onEquipmentChange(tool, entry, context, otherSlot);
        }
      }
    }
  }
  // fire event for modifiers that want to watch equipment when not equipped
  MinecraftForge.EVENT_BUS.post(new ToolEquipmentChangeEvent(context));
}

